function formatBytes(bytes){return bytes<1000?bytes+' B':bytes<1000000?(bytes/1000).toFixed(1)+' KB':(bytes/1000000).toFixed(4)+' MB';}
function exportSettings(){const jpg=$('exportFormat').value==='jpg';return{jpg,type:jpg?'image/jpeg':'image/png',extension:jpg?'jpg':'png',quality:jpg?Number($('jpegQuality').value)/100:undefined};}
function makeArtworkCanvas(){const out=document.createElement('canvas');out.width=source.width;out.height=source.height;const output=out.getContext('2d');output.drawImage(source,0,0);if(hasMask){const alpha=document.createElement('canvas');alpha.width=mask.width;alpha.height=mask.height;const a=alpha.getContext('2d');a.filter=Number($('feather').value)?`blur(${$('feather').value}px)`:'none';a.drawImage(mask,0,0);output.globalCompositeOperation='destination-in';output.drawImage(alpha,0,0);output.globalCompositeOperation='source-over';}for(const layer of layers)if(layer.visible)output.drawImage(layer.asset,layer.x,layer.y,layer.width,layer.height);return out;}
function makeExportCanvas(){const out=makeArtworkCanvas();if(exportSettings().jpg||background==='white'){const output=out.getContext('2d');output.globalCompositeOperation='destination-over';output.fillStyle='#fff';output.fillRect(0,0,out.width,out.height);output.globalCompositeOperation='source-over';}return out;}
async function encodeExport(out,settings){const blob=await new Promise(resolve=>out.toBlob(resolve,settings.type,settings.quality));if(!blob)return null;const bytes=stampResolution(new Uint8Array(await blob.arrayBuffer()),settings.type,currentDpi());return new Blob([bytes],{type:settings.type});}
function scheduleExportInfo(){clearTimeout(exportTimer);const revision=++exportRevision;if(!hasImage)return;$('exportInfo').textContent=`Salida: ${cmDimensions(source.width,source.height)} · calculando peso…`;$('currentInfo').textContent=`${cmDimensions(source.width,source.height)} · calculando peso…`;exportTimer=setTimeout(async()=>{try{const settings=exportSettings(),blob=await encodeExport(makeExportCanvas(),settings);if(revision!==exportRevision||!hasImage)return;$('exportInfo').textContent=blob?`Salida ${settings.extension.toUpperCase()}: ${cmDimensions(source.width,source.height)} · ${formatBytes(blob.size)} (${source.width} × ${source.height} px · ${currentDpi()} ppp)`:'No se ha podido calcular el peso.';;if(blob)$('currentInfo').textContent=`${cmDimensions(source.width,source.height)} · ${formatBytes(blob.size)} (${settings.extension.toUpperCase()}) · ${source.width} × ${source.height} px · ${currentDpi()} ppp`;}catch{if(revision===exportRevision)$('exportInfo').textContent='Peso disponible al guardar.';}},350);}
function updateExportFormat(){const {jpg}=exportSettings();$('jpegQualityControl').hidden=!jpg;$('save').textContent=jpg?'Guardar JPG ↓':'Guardar PNG ↓';document.querySelectorAll('[data-bg]').forEach(b=>{b.disabled=jpg&&b.dataset.bg==='transparent';const selected=b.dataset.bg===(jpg?'white':background);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});render();}
$('exportFormat').onchange=updateExportFormat;$('jpegQuality').oninput=()=>{$('jpegQualityValue').textContent=$('jpegQuality').value+' %';scheduleExportInfo();};
async function exportImage({allowOriginal=false}={}){if(!hasImage||(!hasMask&&!allowOriginal))return false;const settings=exportSettings(),out=makeExportCanvas();const blob=await encodeExport(out,settings);if(!blob){status('No se ha podido crear la imagen.',true);return false;}const name=`${baseName}-sinfondo-${settings.jpg||background==='white'?'blanco':'transparente'}.${settings.extension}`;const file=new File([blob],name,{type:settings.type});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Mi recorte · SinFondo'});status(`${settings.extension.toUpperCase()} · ${formatBytes(blob.size)} entregado al menú de compartir. Elige «Guardar en Archivos» para conservarlo.`);}else{const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status(`${settings.extension.toUpperCase()} · ${formatBytes(blob.size)} preparado para descargar.`);}return true;}catch(err){if(err.name==='AbortError'){status('Guardado cancelado. Tu recorte sigue aquí.');return false;}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.textContent='Descargar tu '+settings.extension.toUpperCase();$('status').replaceChildren(a);if($('replacePhotoDialog').open){const link=a.cloneNode(true);$('replacePhotoText').replaceChildren('Usa este enlace para guardar la foto antes de continuar: ',link);}setTimeout(()=>URL.revokeObjectURL(url),300000);return false;}}
$('save').onclick=()=>exportImage({allowOriginal:true}).catch(()=>status('No se ha podido guardar la imagen. Inténtalo de nuevo.',true));
async function offlineAvailable(){const cache=await caches.open(OFFLINE_CACHE);return(await Promise.all(OFFLINE_FILES.map(path=>cache.match(path)))).every(Boolean);}
async function prepareOffline(){const registration=await navigator.serviceWorker.ready;const active=registration.active;if(active&&active.state!=='activated')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('La actualización sigue activándose. Vuelve a intentarlo.')),15000);const onChange=()=>{if(active.state==='activated'){clearTimeout(timer);active.removeEventListener('statechange',onChange);resolve();}else if(active.state==='redundant'){clearTimeout(timer);active.removeEventListener('statechange',onChange);reject(Error('La app se está actualizando. Recárgala y vuelve a intentarlo.'));}};active.addEventListener('statechange',onChange);onChange();});const cache=await caches.open(OFFLINE_CACHE);let i=0;for(const path of OFFLINE_FILES){const progress=`Guardando archivos ${++i} de ${OFFLINE_FILES.length}… Mantén la app abierta.`;$('offlineText').textContent=progress;networkIndicator.setPreparing(progress);if(!await cache.match(path)){const response=await fetch(path,{cache:'reload'});if(!response.ok)throw Error('No se pudo guardar '+path);await cache.put(path,response);}}return{ready:await offlineAvailable()};}
function offlineState(ready){offlinePrepared=ready;networkIndicator.setPrepared(ready);$('offlineTitle').textContent=ready?'Lista sin conexión':'Prepara tu estudio sin conexión';$('offlineText').textContent=ready?'App e IA guardadas en este dispositivo. Ya puedes usar el modo avión.':'Guarda la app y la IA en este móvil una vez (unos 38 MB).';$('offlineBtn').textContent=ready?'Comprobar':'Preparar';}
$('offlineBtn').onclick=async()=>{if(!('serviceWorker'in navigator)||!isSecureContext){$('offlineText').textContent='Abre la app desde una dirección HTTPS para poder instalarla.';return;}if(offlinePreparing)return;offlinePreparing=true;$('offlineBtn').disabled=true;networkIndicator.setPreparing('Preparando los archivos para trabajar sin Internet…');try{const result=await prepareOffline();offlineState(result.ready);try{await navigator.storage?.persist?.();}catch{}}catch(err){networkIndicator.setPrepared(false);$('offlineTitle').textContent='Preparación incompleta';$('offlineText').textContent=err.message+' Mantén Internet y la app abierta, y vuelve a pulsar Preparar.';}finally{offlinePreparing=false;$('offlineBtn').disabled=false;}};
if(location.protocol==='file:'){status('Para usar la IA e instalar la app, abre estos archivos desde un servidor HTTPS. Consulta LEEME.md.',true);$('offlineBtn').disabled=true;$('photo').disabled=true;}else if('serviceWorker'in navigator && isSecureContext){navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;offlineState(await offlineAvailable());serviceWorkerAvailable=true;maybeAutoPrepare();}).catch(()=>{$('offlineText').textContent='No se ha podido activar el modo sin conexión. Recarga la app desde HTTPS.';});}

