function rgb(hex){return hex.slice(1).match(/../g).map(x=>parseInt(x,16));}
function mix(a,b,t){const aa=rgb(a),bb=rgb(b);return '#'+aa.map((v,i)=>Math.round(v*(1-t)+bb[i]*t).toString(16).padStart(2,'0')).join('');}
function luminance(hex){const c=rgb(hex).map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;});return .2126*c[0]+.7152*c[1]+.0722*c[2];}
function contrast(a,b){const x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
function readable(color,paper,target){let result=color;for(let n=0;n<=100&&contrast(result,paper)<target;n++)result=mix(color,'#101014',n/100);return result;}
function applyTheme(id,start,end,persist=true){
 if(!/^#[0-9a-f]{6}$/i.test(start)||!/^#[0-9a-f]{6}$/i.test(end))return;
 let paper=mix(end,'#ffffff',.18);while(luminance(paper)<.55)paper=mix(paper,'#ffffff',.08);
 const surface=mix(end,'#ffffff',.93),ink=readable(mix(start,'#181310',.45),paper,8);
 const accent=readable(start,paper,5),muted=readable(mix(ink,paper,.3),paper,4.6);
 const tokens=id==='brown'?{'ink':'#483026','muted':'#806b5f','paper':'#f8f5ef','line':'#e6ddd2','accent':'#815739','soft':'#efe4d7','surface':'#fffdfa','surface-muted':'#faf7f2','banner':'#eee6da','shadow':'#48302612','page-glow':'#f0e5d5'}:{ink,muted,paper,accent,line:mix(ink,paper,.84),soft:mix(start,surface,.83),surface,'surface-muted':mix(end,'#ffffff',.72),banner:mix(start,surface,.88),shadow:ink+'12','page-glow':mix(start,paper,.83)};
 for(const [key,value]of Object.entries(tokens))document.documentElement.style.setProperty('--'+key,value);
 document.querySelector('meta[name="theme-color"]').content=tokens.ink;
 $('themeStart').value=start;$('themeEnd').value=end;
 document.querySelectorAll('.theme-option').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===id)));
 if(persist){try{localStorage.setItem('sinfondo-theme',JSON.stringify({id,start,end}));}catch{}}
 if(hasImage)drawOverlay();
}
for(const [id,name,start,end]of themes){const button=document.createElement('button');button.type='button';button.className='theme-option';button.dataset.theme=id;button.setAttribute('aria-pressed',String(id==='brown'));button.setAttribute('aria-label',name+(id==='brown'?' (por defecto)':''));const swatch=document.createElement('span');swatch.className='theme-swatch';swatch.setAttribute('aria-hidden','true');swatch.style.setProperty('--swatch-start',start);swatch.style.setProperty('--swatch-end',end);const label=document.createElement('span');label.className='theme-name';label.textContent=name;button.append(swatch,label);button.onclick=()=>applyTheme(id,start,end);$('themePresets').append(button);}
try{const saved=JSON.parse(localStorage.getItem('sinfondo-theme'));if(saved&&typeof saved.id==='string')applyTheme(saved.id,saved.start,saved.end,false);}catch{}
