function currentDpi(){const n=Number($('outputDpi').value);return Number.isFinite(n)?Math.max(36,Math.min(1200,Math.round(n))):300;}
function cmValue(px){const cm=pixelToCm(px,currentDpi());return new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:cm<.1?4:2}).format(cm);}
function cmDimensions(w,h){return `${cmValue(w)} × ${cmValue(h)} cm`;}
function syncDimensionFields(){if(!hasImage)return;$('canvasWidthCm').value=pixelToCm(source.width,currentDpi()).toFixed(4);$('canvasHeightCm').value=pixelToCm(source.height,currentDpi()).toFixed(4);$('dimensions').textContent=cmDimensions(source.width,source.height);if(sourceMeta){const dpi=sourceMeta.dpi;const known=dpi&&Number.isFinite(dpi.x)&&Number.isFinite(dpi.y)&&dpi.x>0&&dpi.y>0;const x=known?dpi.x:currentDpi(),y=known?dpi.y:currentDpi();const cm=(px,d)=>new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:pixelToCm(px,d)<.1?4:2}).format(pixelToCm(px,d));const ppp=known?`${Math.round(dpi.x)}${Math.abs(dpi.x-dpi.y)>.5?' × '+Math.round(dpi.y):''} ppp del archivo`:`ppp no indicados; cm a ${currentDpi()} ppp de referencia`;$('sourceInfo').textContent=`${cm(sourceMeta.width,x)} × ${cm(sourceMeta.height,y)} cm · ${formatBytes(sourceMeta.bytes)} (${sourceMeta.width} × ${sourceMeta.height} px · ${ppp})`;}updateLayerFields();}
function trimHistoryMemory(){const total=()=>{const assets=new Set(layers.map(l=>l.asset));let bytes=0;for(const h of [...history,...future]){bytes+=(h.alpha?.byteLength||0)+(h.source?.byteLength||0);for(const l of h.layers||[])assets.add(l.asset);}for(const asset of assets)bytes+=asset.width*asset.height*4;return bytes;};while(total()>64*1024*1024&&history.length>1)history.shift();while(total()>64*1024*1024&&future.length>1)future.shift();}
function invalidateAnalysis(){clearTimeout(watchdog);worker?.terminate();worker=null;ready=false;pendingAction=null;magneticEdges=null;}
function refreshSourcePixels(){sourceRGBA=source.getContext('2d').getImageData(0,0,source.width,source.height).data;transparentSource=false;for(let i=3;i<sourceRGBA.length;i+=4)if(sourceRGBA[i]<250){transparentSource=true;break;}}
function setBasePixels(width,height,rgba){validateSize(width,height);for(const c of [source,mask,cut,soft,canvas,overlay]){c.width=width;c.height=height;}source.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(rgba),width,height),0,0);refreshSourcePixels();}
function transformGeometry(width,height,sx,sy,tx,ty){validateSize(width,height);const next=document.createElement('canvas'),nextMask=document.createElement('canvas');next.width=nextMask.width=width;next.height=nextMask.height=height;const a=next.getContext('2d');a.imageSmoothingQuality='high';a.setTransform(sx,0,0,sy,tx,ty);a.drawImage(source,0,0);const m=nextMask.getContext('2d');m.imageSmoothingQuality='high';m.setTransform(sx,0,0,sy,tx,ty);m.drawImage(mask,0,0);pushHistory('geometry');const wasMasked=hasMask;setBasePixels(width,height,a.getImageData(0,0,width,height).data);mask.getContext('2d').drawImage(nextMask,0,0);hasMask=wasMasked;layers=layers.map(layer=>({...layer,x:layer.x*sx+tx,y:layer.y*sy+ty,width:layer.width*sx,height:layer.height*sy}));points=[];lassoAnchors=[];lassoSegments=[];candidates=[];candidateBase=null;cropRect=null;invalidateAnalysis();syncDimensionFields();refreshLayerList();setMode('move');layoutView(true);resultView();}
function cropPixels(rect){const x=Math.max(0,Math.min(source.width-1,Math.round(rect.x))),y=Math.max(0,Math.min(source.height-1,Math.round(rect.y))),width=Math.max(1,Math.min(source.width-x,Math.round(rect.width))),height=Math.max(1,Math.min(source.height-y,Math.round(rect.height)));transformGeometry(width,height,1,1,-x,-y);status('Recorte aplicado. Puedes deshacerlo y recuperar los márgenes.');}
function drawCrop(){if(!cropRect)return;const{x,y,width:w,height:h}=cropRect,W=canvas.width,H=canvas.height,scale=1/view.scale;octx.fillStyle='#0008';octx.fillRect(0,0,W,y*H);octx.fillRect(0,(y+h)*H,W,(1-y-h)*H);octx.fillRect(0,y*H,x*W,h*H);octx.fillRect((x+w)*W,y*H,(1-x-w)*W,h*H);octx.strokeStyle='#fff';octx.lineWidth=2*scale;octx.strokeRect(x*W,y*H,w*W,h*H);for(const p of cropCorners()){octx.fillStyle='#fff';octx.fillRect(p.x*W-5*scale,p.y*H-5*scale,10*scale,10*scale);octx.strokeStyle='#483026';octx.lineWidth=scale;octx.strokeRect(p.x*W-5*scale,p.y*H-5*scale,10*scale,10*scale);}}
function cropCorners(){return cropRect?[{x:cropRect.x,y:cropRect.y},{x:cropRect.x+cropRect.width,y:cropRect.y},{x:cropRect.x+cropRect.width,y:cropRect.y+cropRect.height},{x:cropRect.x,y:cropRect.y+cropRect.height}]:[];}
function updateCropInfo(){if(cropRect)$('cropInfo').textContent=`Recorte: ${cmDimensions(Math.round(cropRect.width*source.width),Math.round(cropRect.height*source.height))}`;}
$('startCrop').onclick=()=>{setMode('crop');$('viewport').scrollIntoView({block:'center'});};$('cancelCrop').onclick=()=>{cropRect=null;setMode('move');};
$('applyCrop').onclick=()=>{if(cropRect)cropPixels({x:cropRect.x*source.width,y:cropRect.y*source.height,width:cropRect.width*source.width,height:cropRect.height*source.height});};
$('trimEmpty').onclick=()=>{const art=makeArtworkCanvas(),bounds=contentBounds(art.getContext('2d').getImageData(0,0,art.width,art.height).data,art.width,art.height);if(!bounds){status('La imagen está vacía; no hay contenido que encajar.');return;}if(bounds.width===source.width&&bounds.height===source.height){status('No se han encontrado márgenes transparentes o blancos vacíos.');return;}cropPixels(bounds);};
function keepSizeRatio(changed){if(!$('sizeLock').checked||!hasImage)return;const n=Number($(changed).value);if(!Number.isFinite(n)||n<=0)return;if(changed==='canvasWidthCm')$('canvasHeightCm').value=(n*source.height/source.width).toFixed(4);else $('canvasWidthCm').value=(n*source.width/source.height).toFixed(4);}
for(const id of ['canvasWidthCm','canvasHeightCm'])$(id).oninput=()=>keepSizeRatio(id);
$('outputDpi').onchange=()=>{$('outputDpi').value=currentDpi();syncDimensionFields();scheduleExportInfo();};
$('scalePhoto').onchange=()=>{$('canvasAnchor').disabled=$('scalePhoto').checked;};
$('addSpace').onclick=()=>{$('canvasWidthCm').value=(pixelToCm(source.width,currentDpi())*1.2).toFixed(4);$('canvasHeightCm').value=(pixelToCm(source.height,currentDpi())*1.2).toFixed(4);$('scalePhoto').checked=false;$('canvasAnchor').disabled=false;};
$('applySize').onclick=()=>{try{const cw=Number($('canvasWidthCm').value),ch=Number($('canvasHeightCm').value);if(!Number.isFinite(cw)||!Number.isFinite(ch)||cw<=0||ch<=0)throw Error('Indica un ancho y un alto positivos en centímetros.');const width=cmToPixel(cw,currentDpi()),height=cmToPixel(ch,currentDpi());validateSize(width,height);if(width===source.width&&height===source.height){status('El tamaño ya coincide con esas dimensiones.');return;}if($('scalePhoto').checked)transformGeometry(width,height,width/source.width,height/source.height,0,0);else{const offset=anchoredOffset(source.width,source.height,width,height,$('canvasAnchor').value);transformGeometry(width,height,1,1,offset.x,offset.y);}status('Tamaño aplicado. Antes y después muestran dimensiones y peso por separado.');}catch(e){status(e.message,true);}};

function activeLayer(){return layers.find(l=>l.id===selectedLayer);}
function layerCorners(layer){return [{x:layer.x/source.width,y:layer.y/source.height},{x:(layer.x+layer.width)/source.width,y:layer.y/source.height},{x:(layer.x+layer.width)/source.width,y:(layer.y+layer.height)/source.height},{x:layer.x/source.width,y:(layer.y+layer.height)/source.height}];}
function drawSelectedLayer(){const layer=activeLayer();if(!layer||!layer.visible)return;const scale=1/view.scale;octx.strokeStyle='#fff';octx.lineWidth=3*scale;octx.strokeRect(layer.x,layer.y,layer.width,layer.height);octx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--ink').trim();octx.lineWidth=scale;octx.strokeRect(layer.x,layer.y,layer.width,layer.height);for(const p of layerCorners(layer)){octx.fillStyle='#fff';octx.fillRect(p.x*source.width-6*scale,p.y*source.height-6*scale,12*scale,12*scale);octx.strokeRect(p.x*source.width-6*scale,p.y*source.height-6*scale,12*scale,12*scale);}}
function updateLayerFields(){const layer=activeLayer();$('layerControls').hidden=!layer;if(!layer)return;$('layerWidthCm').value=pixelToCm(layer.width,currentDpi()).toFixed(4);$('layerHeightCm').value=pixelToCm(layer.height,currentDpi()).toFixed(4);}
function refreshLayerList(){const list=$('layerList');list.replaceChildren();layers.forEach((layer,index)=>{const row=document.createElement('div');row.className='layer-row'+(layer.id===selectedLayer?' active':'');const image=document.createElement('img');image.src=layer.preview;image.alt='';const name=document.createElement('button');name.className='layer-name';name.textContent=`${index+1}. ${layer.name}`;name.title='Seleccionar y editar capa';name.onclick=()=>{selectedLayer=layer.id;setMode('layers');refreshLayerList();};const toggle=document.createElement('button');toggle.textContent=layer.visible?'Ocultar':'Mostrar';toggle.setAttribute('aria-label',`${layer.visible?'Ocultar':'Mostrar'} capa ${index+1}`);toggle.onclick=()=>{pushHistory('layers');layer.visible=!layer.visible;refreshLayerList();render();};row.append(image,name,toggle);list.append(row);});updateLayerFields();}
function canvasPreview(asset){const c=document.createElement('canvas');c.width=c.height=64;const r=Math.min(64/asset.width,64/asset.height);c.getContext('2d').drawImage(asset,(64-asset.width*r)/2,(64-asset.height*r)/2,asset.width*r,asset.height*r);return c.toDataURL('image/png');}
function addLayer(asset,name){if(busy)return;if(!hasImage){status('Abre primero una foto para poder pegar encima.',true);return;}if(layers.length>=8||layers.reduce((n,l)=>n+l.asset.width*l.asset.height,0)+asset.width*asset.height>8388608){status('Puedes usar hasta 8 capas, con un máximo conjunto de 8,4 millones de píxeles.',true);return;}pushHistory('layers');const ratio=Math.min(source.width*.55/asset.width,source.height*.65/asset.height,1);const width=Math.max(1,asset.width*ratio),height=Math.max(1,asset.height*ratio);const layer={id:crypto.randomUUID(),name:name.slice(0,70),asset,preview:canvasPreview(asset),x:(source.width-width)/2,y:(source.height-height)/2,width,height,visible:true};layers.push(layer);trimHistoryMemory();selectedLayer=layer.id;$('layersPanel').open=true;setMode('layers');refreshLayerList();render();status('Capa añadida. Muévela o cambia su tamaño y pulsa OK. Guarda un proyecto para editarla otro día.');}
async function imageAsset(blob){const url=URL.createObjectURL(blob);try{const img=new Image();img.src=url;await img.decode();const r=Math.min(1,2048/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*r));c.height=Math.max(1,Math.round(img.naturalHeight*r));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c;}finally{URL.revokeObjectURL(url);}}
function addTextLayer(text){text=text.trim().slice(0,3000);if(!text){status('No hay texto que pegar.');return;}const lines=text.split(/\r?\n/).flatMap(line=>line.match(/.{1,45}/g)||['']).slice(0,30);const c=document.createElement('canvas'),measure=c.getContext('2d');measure.font='48px -apple-system, Arial, sans-serif';c.width=Math.min(2048,Math.max(40,Math.ceil(Math.max(...lines.map(t=>measure.measureText(t).width))+24)));c.height=Math.min(2048,lines.length*64+24);const x=c.getContext('2d');x.font='48px -apple-system, Arial, sans-serif';x.textBaseline='top';x.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--ink').trim();lines.forEach((line,i)=>x.fillText(line,12,12+i*64));addLayer(c,'Texto: '+text.slice(0,35));}
$('pasteLayer').onclick=async()=>{try{if(navigator.clipboard?.read){const items=await navigator.clipboard.read();for(const item of items){const type=item.types.find(t=>t.startsWith('image/'));if(type){addLayer(await imageAsset(await item.getType(type)),'Imagen pegada');return;}}for(const item of items)if(item.types.includes('text/plain')){addTextLayer(await (await item.getType('text/plain')).text());return;}}else if(navigator.clipboard?.readText){addTextLayer(await navigator.clipboard.readText());return;}status('No hay una imagen o texto disponible. Usa Pegar del sistema o Añadir imagen.',true);}catch{status('El navegador no ha permitido leer el portapapeles. Usa Ctrl/Cmd + V o Añadir imagen.',true);}};
document.addEventListener('paste',async e=>{if(!hasImage||busy||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;const file=[...(e.clipboardData?.files||[])].find(f=>f.type.startsWith('image/'));try{if(file){e.preventDefault();addLayer(await imageAsset(file),'Imagen pegada');return;}const text=e.clipboardData?.getData('text/plain');if(text){e.preventDefault();addTextLayer(text);}}catch{status('No se ha podido abrir el contenido pegado.',true);}});
$('layerFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{addLayer(await imageAsset(file),file.name);}catch{status('No se puede abrir esa imagen para la capa.',true);}finally{$('layerFile').value='';}};
for(const id of ['layerFile','projectFile'])document.querySelectorAll(`label[for="${id}"]`).forEach(label=>label.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$(id).click();}}));
for(const id of ['layerWidthCm','layerHeightCm'])$(id).oninput=()=>{const layer=activeLayer();if(!layer||!$('layerLock').checked)return;const value=Number($(id).value);if(value<=0)return;if(id==='layerWidthCm')$('layerHeightCm').value=(value*layer.height/layer.width).toFixed(4);else $('layerWidthCm').value=(value*layer.width/layer.height).toFixed(4);};
$('layerApplySize').onclick=()=>{const layer=activeLayer();if(!layer)return;const w=Number($('layerWidthCm').value),h=Number($('layerHeightCm').value);if(!Number.isFinite(w)||!Number.isFinite(h)||w<=0||h<=0){status('Indica dimensiones positivas para la capa.',true);return;}const width=cmToPixel(w,currentDpi()),height=cmToPixel(h,currentDpi());if(width>8192||height>8192){status('La capa no puede superar 8192 píxeles por lado.',true);return;}pushHistory('layers');layer.width=width;layer.height=height;updateLayerFields();render();};
$('layerDelete').onclick=()=>{if(!activeLayer())return;pushHistory('layers');layers=layers.filter(l=>l.id!==selectedLayer);selectedLayer=layers.at(-1)?.id||null;refreshLayerList();render();};$('layerDone').onclick=()=>{selectedLayer=null;setMode('move');refreshLayerList();render();status('Capa colocada. Selecciónala en la lista para volver a editarla.');};

function moveSpecial(e,delta){if(!single?.moved)return;const p=imagePoint(e);if(mode==='layers'&&!single.layerId){view.pan(delta.x,delta.y);updateView();return;}if(!single.edited){strokeHistory=[...history];strokeFuture=[...future];pushHistory(mode==='layers'?'layers':'points');single.edited=true;}
 if(mode==='crop'){const r=single.cropStart,W=source.width,H=source.height;let box;if(single.corner>=0)box=resizeRectangle({x:r.x*W,y:r.y*H,width:r.width*W,height:r.height*H},single.corner,{x:Math.max(0,Math.min(W,p.x*W)),y:Math.max(0,Math.min(H,p.y*H))});else if(single.cropMove)box={x:Math.max(0,Math.min(W-r.width*W,(r.x+p.x-single.imageStart.x)*W)),y:Math.max(0,Math.min(H-r.height*H,(r.y+p.y-single.imageStart.y)*H)),width:r.width*W,height:r.height*H};else{const a=single.imageStart;box={x:Math.max(0,Math.min(a.x,p.x)*W),y:Math.max(0,Math.min(a.y,p.y)*H),width:Math.max(1,Math.abs(a.x-p.x)*W),height:Math.max(1,Math.abs(a.y-p.y)*H)};}box.x=Math.max(0,Math.min(W-1,box.x));box.y=Math.max(0,Math.min(H-1,box.y));box.width=Math.max(1,Math.min(W-box.x,box.width));box.height=Math.max(1,Math.min(H-box.y,box.height));cropRect={x:box.x/W,y:box.y/H,width:box.width/W,height:box.height/H};updateCropInfo();drawOverlay();
 }else{const layer=layers.find(l=>l.id===single.layerId);if(!layer)return;const start=single.layerStart;let box;if(single.corner>=0)box=resizeRectangle(start,single.corner,{x:p.x*source.width,y:p.y*source.height},$('layerLock').checked);else box={...start,x:start.x+(p.x-single.imageStart.x)*source.width,y:start.y+(p.y-single.imageStart.y)*source.height};layer.x=Math.max(-8192,Math.min(source.width,box.x));layer.y=Math.max(-8192,Math.min(source.height,box.y));layer.width=Math.max(1,Math.min(8192,box.width));layer.height=Math.max(1,Math.min(8192,box.height));updateLayerFields();render();}
}

async function offerFile(blob,name,title){const file=new File([blob],name,{type:blob.type});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title});return true;}const link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);return true;}catch(e){if(e.name==='AbortError')return false;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.textContent='Descargar proyecto';$('status').replaceChildren(link);setTimeout(()=>URL.revokeObjectURL(url),300000);return false;}}
async function saveProject(){if(!hasImage||busy)return;try{const project={format:'sinfondo',version:1,width:source.width,height:source.height,baseName,sourceMeta,original:originalAsset?.toDataURL('image/png'),dpi:currentDpi(),background,exportFormat:$('exportFormat').value,quality:Number($('jpegQuality').value),feather:Number($('feather').value),hasMask,base:source.toDataURL('image/png'),mask:hasMask?mask.toDataURL('image/png'):null,layers:layers.map(l=>({id:l.id,name:l.name,x:l.x,y:l.y,width:l.width,height:l.height,visible:l.visible,image:l.asset.toDataURL('image/png')}))};const blob=new Blob([JSON.stringify(project)],{type:'application/json'});if(blob.size>70*1024*1024)throw Error('El proyecto supera 70 MB. Reduce el lienzo o elimina capas para poder guardarlo en el móvil.');status(`Proyecto preparado: ${formatBytes(blob.size)}. Incluye foto, retoques y capas.`);const saved=await offerFile(blob,baseName+'.sinfondo','Proyecto editable · SinFondo');if(saved)status('Proyecto entregado al guardado. Conserva el archivo .sinfondo para volver a editar las capas.');else if(!$('status').querySelector('a'))status('Guardado del proyecto cancelado. El trabajo sigue abierto.');return saved;}catch(err){status(err.message||'No se ha podido guardar el proyecto. La foto y sus capas siguen abiertas.',true);return false;}}
$('saveProject').onclick=saveProject;
$('replaceProjectSave').onclick=async()=>{for(const id of ['replacePhotoSave','replaceProjectSave','replacePhotoConfirm','replacePhotoCancel'])$(id).disabled=true;try{const saved=await saveProject();$('replacePhotoText').textContent=saved?'Proyecto preparado para guardar. Cuando hayas terminado de guardarlo, puedes cerrar la foto y elegir otra.':'El proyecto sigue abierto. Completa el guardado antes de sustituir la foto si quieres conservar las capas.';}finally{for(const id of ['replacePhotoSave','replaceProjectSave','replacePhotoConfirm','replacePhotoCancel'])$(id).disabled=false;}};
async function dataImage(value){if(typeof value!=='string'||!/^data:image\/png;base64,/.test(value)||value.length>60000000)throw Error('El proyecto contiene una imagen no válida.');const header=Uint8Array.from(atob(value.slice(22,66)),c=>c.charCodeAt(0));if(header.length<24||header[0]!==137||header[1]!==80)throw Error('La imagen del proyecto no es PNG.');const size=new DataView(header.buffer);validateSize(size.getUint32(16),size.getUint32(20));const img=new Image();img.src=value;await img.decode();validateSize(img.naturalWidth,img.naturalHeight);const asset=document.createElement('canvas');asset.width=img.naturalWidth;asset.height=img.naturalHeight;asset.getContext('2d').drawImage(img,0,0);return asset;}
$('projectFile').onchange=async e=>{const file=e.target.files[0];if(!file||busy)return;setBusy(true);status('Abriendo proyecto con capas…');try{if(file.size>70*1024*1024)throw Error('El proyecto supera los 70 MB admitidos en el móvil.');const p=JSON.parse(await file.text());if(p.format!=='sinfondo'||p.version!==1)throw Error('Este archivo no es un proyecto SinFondo compatible.');validateSize(p.width,p.height);if(!Array.isArray(p.layers)||p.layers.length>8)throw Error('El proyecto tiene demasiadas capas.');const base=await dataImage(p.base);if(base.width!==p.width||base.height!==p.height)throw Error('Las dimensiones del proyecto no coinciden.');const importedOriginal=p.original?await dataImage(p.original):copyCanvas(base);const editMask=p.hasMask?await dataImage(p.mask):null;if(editMask&&(editMask.width!==p.width||editMask.height!==p.height))throw Error('La máscara no coincide con la imagen.');const imported=[];let assetPixels=0;for(const layer of p.layers){if(![layer.x,layer.y,layer.width,layer.height].every(Number.isFinite)||layer.width<1||layer.height<1||layer.width>8192||layer.height>8192||Math.abs(layer.x)>8192||Math.abs(layer.y)>8192)throw Error('Una capa tiene dimensiones no válidas.');const asset=await dataImage(layer.image);assetPixels+=asset.width*asset.height;if(assetPixels>8388608)throw Error('Las capas del proyecto superan el tamaño admitido.');imported.push({id:crypto.randomUUID(),name:String(layer.name||'Capa').slice(0,70),asset,preview:canvasPreview(asset),x:layer.x,y:layer.y,width:layer.width,height:layer.height,visible:layer.visible!==false});}
 invalidateAnalysis();setBasePixels(base.width,base.height,base.getContext('2d').getImageData(0,0,base.width,base.height).data);originalAsset=importedOriginal;hasImage=true;hasMask=!!editMask;if(editMask)mask.getContext('2d').drawImage(editMask,0,0);layers=imported;selectedLayer=null;cropRect=null;points=[];history=[];future=[];lassoAnchors=[];lassoSegments=[];candidates=[];candidateBase=null;baseName=String(p.baseName||file.name.replace(/\.sinfondo$/i,'')).slice(0,100);sourceMeta=p.sourceMeta&&[p.sourceMeta.width,p.sourceMeta.height,p.sourceMeta.bytes].every(Number.isFinite)&&p.sourceMeta.width>0&&p.sourceMeta.height>0&&p.sourceMeta.bytes>=0?p.sourceMeta:{width:base.width,height:base.height,bytes:file.size};$('outputDpi').value=Number.isFinite(p.dpi)?Math.max(36,Math.min(1200,p.dpi)):300;$('feather').value=Number.isFinite(p.feather)?Math.max(0,Math.min(3,p.feather)):0;background=p.background==='white'?'white':'transparent';$('exportFormat').value=p.exportFormat==='jpg'?'jpg':'png';$('jpegQuality').value=Number.isFinite(p.quality)?Math.max(60,Math.min(100,p.quality)):92;$('jpegQualityValue').textContent=$('jpegQuality').value+' %';$('empty').hidden=true;$('editor').hidden=false;showOriginal=false;$('original').textContent='Ver foto base';$('original').setAttribute('aria-pressed','false');syncDimensionFields();refreshLayerList();setMode('move');layoutView(true);updateExportFormat();setBusy(false);status('Proyecto abierto. La foto, el recorte y las capas siguen siendo editables.');
 }catch(err){setBusy(false);status('No se ha podido abrir el proyecto: '+err.message,true);}finally{$('projectFile').value='';}};

function copyCanvas(input){const out=document.createElement('canvas');out.width=input.width;out.height=input.height;out.getContext('2d').drawImage(input,0,0);return out;}
$('returnOriginal').onclick=()=>{if(!hasImage||!originalAsset||busy)return;pushHistory('geometry');const asset=originalAsset;invalidateAnalysis();setBasePixels(asset.width,asset.height,asset.getContext('2d').getImageData(0,0,asset.width,asset.height).data);hasMask=false;layers=[];selectedLayer=null;cropRect=null;points=[];lassoAnchors=[];lassoSegments=[];candidates=[];candidateBase=null;$('feather').value='0.5';syncDimensionFields();refreshLayerList();setMode('move');layoutView(true);resultView();status('Foto original recuperada. Puedes deshacer esta restauración para recuperar los retoques y las capas.');};

function maybeAutoPrepare(){if(serviceWorkerAvailable&&!offlinePrepared&&!offlinePreparing&&!autoPrepareAttempted&&networkIndicator.state?.connected){autoPrepareAttempted=true;$('offlineBtn').click();}}
window.addEventListener('sinfondo-connection-change',event=>{if(event.detail?.connected)maybeAutoPrepare();});
